            r2 = lock2.rows.tracked_remove(new_row as nat);
        }

        let mut entry1 = *self.matrix[old_row].borrow(Tracked(&r1.pt));
        let mut entry2 = *self.matrix[new_row].borrow(Tracked(&r2.pt));

